package ro.whistlab.core.ai.information;
import ro.whistlab.core.testing.match.PlayerObservations;

import ro.whistlab.core.ai.engine.MonteCarloAi;
import ro.whistlab.core.ai.policy.LostGameContractRegressionTest;
import ro.whistlab.core.model.Trump;
import ro.whistlab.core.testing.CapturedRegression;
import ro.whistlab.core.testing.PublicEndgameOracle;
import static atf.gradle.audit.assertions.GradleAssertions.*;import java.util.*;import com.fasterxml.jackson.databind.*;import org.junit.Test;import org.junit.runner.RunWith;import org.junit.runners.Parameterized;import ro.whistlab.coach.WorldEnumerationProbe;
@RunWith(Parameterized.class)public class SmallWorldEnumerationTest extends atf.gradle.audit.GradleAuditedTest {
 @Parameterized.Parameters(name="pool-case={0}")public static Collection<Object[]> cases(){return List.of(new Object[][]{{0},{1},{2}});}private final int index;public SmallWorldEnumerationTest(int index){this.index=index;}
 static Set<String> keys(List<List<List<Integer>>> worlds){var keys=new TreeSet<String>();for(var w:worlds)keys.add(w.stream().map(h->h.stream().sorted().toList().toString()).toList().toString());return keys;}
 @Test public void everyFeasiblePublicWorldIsRepresentedExactlyOnce()throws Exception{var json=new ObjectMapper();var f=json.readTree(getClass().getResourceAsStream("/regressions/small-worlds/cases.json")).get(index);var v=ro.whistlab.core.testing.codec.ObservedPositionJson.view(json,f.path("before"));var oracle=PublicEndgameOracle.audit(v);var core=MonteCarloAi.enumerateSmallDeals(v).stream().map(w->w.stream().map(h->h.stream().map(PublicEndgameOracle::id).toList()).toList()).toList();var independent=WorldEnumerationProbe.enumerate(PlayerObservations.independent(v));int expected=f.path("expectedWorlds").asInt();var context=new LinkedHashMap<String,Object>();context.put("purpose","Replace a biased/finite random sample by a complete small public distribution");context.put("rule","Enumerate every compatible unordered hand assignment including undealt leftovers; each world has equal combinatorial prior mass. No real hidden hands are inputs. More than256worlds means full fallback, never a truncated prefix.");context.put("origin",f.path("gameId").asText());context.put("before",f.path("before"));context.put("unknownCards",f.path("unknownCount").asInt());context.put("scope","Completeness under public void constraints and a declared continuation model, not an optimal-play guarantee.");
 CapturedRegression.run("world-completeness-pool"+f.path("unknownCount").asInt(),getClass().getName(),"everyFeasiblePublicWorldIsRepresentedExactlyOnce",context,c->{c.equal("Independent list-based rule oracle world count",expected,oracle.worlds());c.equal("Core completes all feasible worlds",expected,core.size());c.equal("Independent completes all feasible worlds",expected,independent.size());c.equal("Core has no repeated hand assignment",core.size(),keys(core).size());c.equal("Independent has no repeated hand assignment",independent.size(),keys(independent).size());c.equal("Independent and core cover the identical complete set",keys(core),keys(independent));
  var available=new HashSet<Integer>(MonteCarloAi.unknownCards(v).stream().map(PublicEndgameOracle::id).toList());available.addAll(v.hand().stream().map(PublicEndgameOracle::id).toList());boolean valid=true;boolean[][] voids=new boolean[4][4];for(int i=0;i<v.history().size();i++){var p=v.history().get(i);var led=v.history().get(i-i%4).card().suit();if(p.card().suit()!=led){voids[p.seat()][led.ordinal()]=true;if(v.trump()!=Trump.NO_TRUMP&&p.card().suit().ordinal()!=v.trump().ordinal())voids[p.seat()][v.trump().ordinal()]=true;}}for(var w:independent){var used=new HashSet<Integer>();for(int s=0;s<4;s++){valid&=w.get(s).size()==v.seats().get(s).remaining();for(int card:w.get(s))valid&=available.contains(card)&&used.add(card)&&!voids[s][card/13];}}c.equal("All worlds preserve card identity, capacities and public voids",true,valid);
 });}
}
